		.pend

abs_w_into_AY	.proc
	; -- AY = abs(AY)
		cpy  #0
		bmi  +
		rts
+		eor  #$ff
		pha
		tya
		eor  #$ff
		tay
		pla
		clc
		adc  #1
		bcc  +
		iny
+		rts
		.pend

abs_l_into_R14R15	.proc
	; -- R14:R15 = abs(R14:R15)
    lda  cx16.r15H
    bmi  +   ; Negative if high bit of highest byte is set
    rts
+
    ; Invert all four bytes
    lda  cx16.r14L
    eor  #$FF
    sta  cx16.r14L
    lda  cx16.r14H
    eor  #$FF
    sta  cx16.r14H
    lda  cx16.r15L
    eor  #$FF
    sta  cx16.r15L
    lda  cx16.r15H
    eor  #$FF
    sta  cx16.r15H
    ; Add 1 to whole 32-bit value
    inc  cx16.r14L
    bne  +
    inc  cx16.r14H
    bne  +
    inc  cx16.r15L
    bne  +
    inc  cx16.r15H
+   rts
		.pend

